function pickQ(tops, re) {
  const forced = S.age ? bandOf(S.age) : null;
  const near = lv => [lv, ...[0, 1, 2].filter(j => j != lv).sort((a, b) => Math.abs(a - lv) - Math.abs(b - lv))];
  const order = forced == null ? [1, 0, 2] : near(forced);
  const seen = new Set(S.seen), all = QB.map((q, i) => [q, i]).filter(([q]) => tops.includes(q[0]));
  const fresh = lv => {
    const pool = all.filter(([q]) => q[1] == lv); if (!pool.length) return [];
    let f = pool.filter(([, i]) => !seen.has(i));
    if (!f.length) { const ids = new Set(pool.map(x => x[1])); S.seen = S.seen.filter(i => !ids.has(i)); f = pool; }
    return f;
  };
  let hit = null;
  pickQ.hit = !re; pickQ.top = 3;
  if (re) for (const lv of order) { const n = fresh(lv).filter(([q]) => re.test(q[2] + ' ' + q[3][q[4]])); if (n.length) { hit = n; pickQ.hit = true; break; } }
  if (!hit) for (const lv of order) { const n = fresh(lv); if (n.length) { hit = n; break; } }
  if (!hit) return null;
  const [q, i] = hit[Math.floor(Math.random() * hit.length)];
  pickQ.top = q[0]; S.seen.push(i); if (S.seen.length > 1200) S.seen = S.seen.slice(-1200);
  return q;
}
