/* شاشة نصيحة اليوم عند فتح التطبيق: 5 ثواني على الأقل وتطول مع طول النص */
function tipSplash() {
  if (!S.setupDone || document.getElementById('tipS') || S.tipDay === dayKey()) return;
  S.tipDay = dayKey(); save();
  const [c, t, src] = tipOf(), C = TIPC[c];
  const words = t.trim().split(/\s+/).length;
  const ms = Math.min(8000, Math.max(3000, 2000 + words * 350));
  const h = new Date().getHours();
  const hi = h < 5 ? 'ليلتك سعيدة' : h < 12 ? 'صباح الخير' : h < 17 ? 'نهارك سعيد' : 'مساء الخير';
  const el = document.createElement('div');
  el.id = 'tipS';
  el.setAttribute('role', 'dialog'); el.setAttribute('aria-modal', 'true'); el.setAttribute('aria-labelledby', 'tipSt');
  el.style.cssText = `--tc:${C[2]};--tl:${C[3]}`;
  el.innerHTML = `
    <div class="ts-card">
      <p class="ts-hi">${hi} يا ${esc(S.name)}</p>
      <div class="ts-ic-w"><div class="ts-ic">${ic(C[0])}</div><i class="spk s1"></i><i class="spk s2"></i><i class="spk s3"></i><i class="spk s4"></i></div>
      <h2 id="tipSt" class="ts-lab">نصيحة اليوم · ${C[1]}</h2>
      <p class="ts-t">${esc(t)}</p>
      ${src ? `<p class="ts-src">${esc(src)}</p>` : ''}
    </div>
    <div class="ts-foot">
      <span class="ts-bar" aria-hidden="true"><b></b></span>
      <button class="btn ts-skip" type="button">يلا نبدأ</button>
    </div>`;
  document.body.append(el);
  document.body.classList.add('lock');
  $('#m').inert = true; $('#nav').inert = true;
  const bar = el.querySelector('.ts-bar b'), skip = el.querySelector('.ts-skip');
  let left = ms, last = performance.now(), paused = false, raf = 0, done = false;
  const end = () => {
    if (done) return; done = true;
    cancelAnimationFrame(raf); document.removeEventListener('keydown', key, true);
    document.body.classList.remove('lock');
    $('#m').inert = false; $('#nav').inert = false;
    el.classList.add('out');
    setTimeout(() => el.remove(), matchMedia('(prefers-reduced-motion: reduce)').matches ? 0 : 380);
    $('#m').focus({ preventScroll: true });
  };
  const key = e => { if (e.key == 'Escape' || e.key == 'Enter' && document.activeElement == skip) { e.preventDefault(); e.stopPropagation(); end(); } };
  document.addEventListener('keydown', key, true);
  skip.addEventListener('click', end);
  const card = el.querySelector('.ts-card');
  ['pointerenter', 'pointerdown'].forEach(ev => card.addEventListener(ev, () => { paused = true; el.classList.add('paused'); }));
  ['pointerleave', 'pointerup', 'pointercancel'].forEach(ev => card.addEventListener(ev, () => { paused = false; el.classList.remove('paused'); }));
  (function loop(now) {
    if (!paused) left -= Math.min(now - last, 100);
    last = now;
    bar.style.transform = `scaleX(${Math.max(0, left / ms)})`;
    if (left <= 0) return end();
    raf = requestAnimationFrame(loop);
  })(performance.now());
  skip.focus({ preventScroll: true });
}

