/* جزيئات هادية حوالين الشجرة */
setInterval(() => {
  if (trReduce() || document.hidden) return;
  document.querySelectorAll('.tr').forEach(t => {
    if (!t.isConnected) return;
    const st = t._st, b = TS[st].box;
    if (Math.random() < [.22, .08, .12, .16, .55][st]) { const q = trSpot(b); trMote(t._fx, q[0], q[1]); }
    if (st === TLAST && Math.random() < .25) { const q = trSpot(b); trMote(t._fx, q[0], q[1]); }
  });
}, 900);

/* ═══════════════════════════════════════════════
   SCREENS
   ═══════════════════════════════════════════════ */
const treeView = (l, from) => `<div class="tree-host" data-l="${l}" ${from ? `data-from="${from}"` : ''} role="img" aria-label="شجرتك، المستوى ${ar(l)}: ${LN[l-1]}"></div>`;

/* شريط "أنت مين" في أول الرئيسية: بيتغيّر حسب الدور، وبيدّي الزرار اللي يناسبه */
function roleBanner() {
  const R = ROLES[S.role] || ROLES.user, k = R.k, f = R.g == 'f', n = esc(S.name);
  const hi = { child: 'أهلاً يا ' + n, user: 'أهلاً يا ' + n, student: 'أهلاً يا ' + n, parent: 'أهلاً يا ' + (f ? 'أم ' : 'أبو ') + n, teacher: 'أهلاً يا ' + (f ? 'أستاذة ' : 'أستاذ ') + n }[k];
  const tx = {
    child: 'جاوب سؤال كل مهمة صح، وشجرتك هتكبر.',
    user: 'مهام يومية وأسئلة على قد مستواك.',
    student: 'أسئلتك على قد سنّك ومرحلتك، وكل إجابة صح بتقرّبك للمستوى الجاي.',
    parent: 'بتتابع ' + n + (S.age ? '، ' + ar(S.age) + ' سنة' : '') + '. الأسئلة على قد سنّه، جاوبوها مع بعض.',
    teacher: 'اعمل مسابقة للطلاب على نفس الجهاز، من ٢ لـ ٤ طلاب.'
  }[k];
  const bt = { child: ['swords', 'تحدّى صاحبك', 'duel'], user: ['swords', 'تحدّى صاحبك', 'duel'], student: ['swords', 'تحدّى زميلك', 'duel'], parent: ['swords', 'تحدّى', 'duel'], teacher: ['swords', 'تحدّى', 'duel'] }[k] || ['swords', 'تحدّى صاحبك', 'duel'];
  const lv = S.age ? 'مستوى ' + AGE_BANDS[bandOf(S.age)].ti + ' · ' + AGE_BANDS[bandOf(S.age)].de : 'أسئلة على مستوى متوسط';
  return `<section class="glass rb rb-${k}" aria-label="${R.bn || R.ti}"><span class="rb-i">${ic(R.ic)}</span><div class="rb-b"><small>${R.bn || R.ti} · ${lv}</small><b>${hi}</b><p>${tx}</p></div><button class="btn s rb-btn" type="button" data-a="${bt[2]}">${ic(bt[0])}${bt[1]}</button></section>`;
}

function home() {
  const l = lvl();
  const lo = LV[l-1];
  const hi = LV[l] || LV[4];
  const p = l == 5 ? 100 : Math.min(100, (S.xp - lo) / (hi - lo) * 100);
  const circ = 2 * Math.PI * 70;
  const dash = circ * (1 - p / 100);
  const N = TASKS.length, dn = S.tasks.filter(Boolean).length, all = dn == N;
  const sk = skyState(), mc = 2 * Math.PI * 18, td = (new Date().getDay() + 1) % 7;

  const taskBtn = i => {
    const t = TASKS[i], k = TT[i], K = KK[k], d = S.tasks[i];
    return `
      <button class="task glass kc kc-${k} ${d ? 'done' : ''}" data-a="task" data-i="${i}" aria-pressed="${!!d}">
        <span class="chk">${d ? ic('check') : ''}</span>
        <span class="tt">${t[0]}<small>${ic(K[1])}<span class="sr">${K[0]}، </span>توفّر ~${IMP[i][0] ? ar(IMP[i][0]) + ' لتر' : ar(IMP[i][1]) + ' ك.و.س'}</small></span>
        <span class="xp">+${ar(t[1])}</span>
      </button>`;
  };
  /* المهام في مجموعات (الصبح · المسا · طول اليوم) والمنتهي ينزل لآخر القايمة */
  const GD = [['الصبح', 'light_mode'], ['المسا', 'dark_mode'], ['طول اليوم', 'task_alt']];
  const gk = t => t[2] == 'صباحاً' ? 0 : t[2] == 'مساءً' ? 1 : 2;
  const idx = TASKS.map((_, i) => i), pend = idx.filter(i => !S.tasks[i]), fin = idx.filter(i => S.tasks[i]);
  const grp = (name, icn, L) => `<div class="grp"><h3 class="grp-h">${ic(icn)}${name}<span class="count">${ar(L.length)}</span></h3>${L.map(taskBtn).join('')}</div>`;
  const groups = GD.map(([n, icn], g) => { const L = pend.filter(i => gk(TASKS[i]) == g); return L.length ? grp(n, icn, L) : ''; }).join('')
    + (fin.length ? grp('خلّصتها النهارده', 'check_circle', fin) : '');

  const nx = CH.map((c, i) => [c, i]).filter(([c, i]) => S.ch[i] != 1 && chP(i) < 100).sort((a, b) => chP(b[1]) - chP(a[1]))[0];
  const wk = weekVals().reduce((a, b) => a + b, 0);

  return `
<h1 class="sr">الرئيسية</h1>
${roleBanner()}
<div class="w home"><div class="side">
<section class="glass tree-card ${all ? 'bloom' : ''}" data-sky="${sk.k}" style="--ox:${sk.x}%;--oy:${sk.y}%">
      <div class="sky" aria-hidden="true" data-sig="${sk.k + sk.orb}">${skyInner(sk)}</div>
      <div class="row">
        <span class="pill a">${ic('eco')}المستوى ${ar(l)}</span>
        <span class="pill g">${ic('local_fire_department')}${ar(S.streak)} يوم</span>
      </div>
      <h2 class="tree-name">${LN[l-1]}</h2>
      <div class="lvdots" aria-hidden="true">${LN.map((_, i) => `<i class="${i < l ? 'on' : ''}${i == l - 1 ? ' cur' : ''}"></i>`).join('')}</div>
      <div class="tree-stage gorb">
        <svg class="ring" viewBox="0 0 156 156" aria-hidden="true">
          <circle cx="78" cy="78" r="70" fill="none" class="rt" stroke-width="8"/>
          <circle cx="78" cy="78" r="70" fill="none" stroke="url(#ringGrad)" stroke-width="8" 
                  stroke-linecap="round" stroke-dasharray="${circ}" stroke-dashoffset="${dash}"
                  transform="rotate(-90 78 78)"/>
          <g class="knob" style="transform:rotate(${((1 - dash / circ) * 360).toFixed(2)}deg)"><circle cx="78" cy="8" r="5.6"/></g>
          <defs>
            <linearGradient id="ringGrad" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0" stop-color="#5FD39A"/>
              <stop offset=".5" stop-color="#1F9A5E"/>
              <stop offset="1" stop-color="#0F6D41"/>
            </linearGradient>
          </defs>
        </svg>
        <i class="gnd"></i>
        ${treeView(l)}
        
      </div>
      
      <div class="xp-line">
        <strong>${ar(S.xp)}${l < 5 ? ' / ' + ar(hi) : ''} XP</strong>
        <span>${l == 5 ? 'وصلت لأعلى مستوى' : 'باقي ' + ar(hi - S.xp) + ' للمستوى ' + ar(l+1)}</span>
      </div>
    </section>
    
    <div class="grid3">
      <div class="stat glass">
        <div class="ic-wrap" style="background:var(--water-light);color:var(--water)">${ic('water_drop')}</div>
        <b style="color:var(--water)">${ar(S.water)}</b>
        <small>لتر</small>
        <small class="eq" title="زجاجة مياه ١٫٥ لتر" ${S.water < 1.5 ? 'style="visibility:hidden"' : ''}>≈ ${ar(Math.round(S.water / 1.5))} زجاجة</small>
      </div>
      <div class="stat glass">
        <div class="ic-wrap" style="background:var(--gold-light);color:var(--gold-dark)">${ic('bolt')}</div>
        <b style="color:var(--gold-dark)">${ar(S.energy)}</b>
        <small>ك.و.س</small>
        <small class="eq" title="تقدير تقريبي لمروحة سقف" ${S.energy < .1 ? 'style="visibility:hidden"' : ''}>≈ ${ar(Math.round(S.energy * 15))} ساعة مروحة</small>
      </div>
      <div class="stat glass">
        <div class="ic-wrap" style="background:var(--accent-light);color:var(--accent)">${ic('savings')}</div>
        <b style="color:var(--accent)">${ar(S.money)}</b>
        <small>جنيه</small>
        <small class="eq" style="visibility:hidden" aria-hidden="true">&nbsp;</small>
      </div>
    </div>
    
    </div><div class="col">
    ${tipCard()}
    <div class="tasks">
      <section class="glass prog-card" aria-label="تقدّم مهام النهارده">
        <div class="mini-w">
          <svg class="mini" viewBox="0 0 44 44" aria-hidden="true">
            <circle cx="22" cy="22" r="18" class="mt"/>
            <circle cx="22" cy="22" r="18" class="mf" style="--c:${mc};--o:${mc * (1 - dn / N)}" transform="rotate(-90 22 22)"/>
          </svg>
          <b>${ar(dn)}</b>
        </div>
        <div class="pc-t">
          <strong>${ar(dn)} من ${ar(N)}</strong>
          <small>${all ? 'خلّصت كل مهام النهارده' : 'باقي ' + ar(N - dn) + ' علشان شجرتك تزهّر'}</small>
        </div>
      </section>
      <p class="swipe-hint">اسحب أي مهمة لليمين أو الشمال علشان تنجزها</p>
      ${all ? `<section class="glass done-card">${ILL.done}<h3>كل مهام النهارده خلصت</h3><p>شجرتك زهّرت، ارجع بكرة علشان تكمّل السلسلة.</p></section>` : ''}
      ${groups}
    </div>
    <div class="extra">
      ${nx ? `<button class="glass next-ch kc kc-${CT[nx[1]]}" data-a="tab" data-i="1">
        <span class="ico">${ic(nx[0][1])}</span>
        <span class="nc-t"><small>أقرب تحدي ليك</small><b>${nx[0][2]}</b>
          <span class="pg"><span class="track"><b class="fill" style="width:${chP(nx[1])}%"></b></span><span>${ar(chP(nx[1]))}٪</span></span>
        </span>
      </button>` : ''}
      <section class="glass wk">
        <h3>توفيرك الأسبوع ده</h3>
        <div class="wk-b" aria-hidden="true">${weekVals().map((v, i) => `<i class="${i == td ? 'td' : ''}" style="height:${Math.max(v / SC * 100, 4)}%"></i>`).join('')}</div>
        <small>${ar(wk)} نقطة</small>
      </section>
    </div></div></div>
  `;
}

function chal() {
  const L = CH.map((c, i) => [c, i]).filter(([c]) => per == 'a' || c[0] == per).sort((a, b) => (b[0][6] >= 100 && S.ch[b[1]] != 1) - (a[0][6] >= 100 && S.ch[a[1]] != 1));
  return `
    <h1 style="margin-top:.5rem">التحديات</h1>
     <p class="sub">أكمل التحديات واكسب مكافآت أكبر</p>
     <div class="px">
       <button class="px-card px-pvp" data-a="duel" type="button">${ic('swords')}<b>مبارزة شد الحبل</b><small>لاعبين بس على نفس الشاشة، والأسرع في الإجابة الصح بيسحب الحبل ناحيته</small><span class="px-tag">تحدّى صاحبك</span></button>
       <button class="px-card px-arc" data-a="arc" type="button">${ic('star')}<b>أركيد</b><small>ألعاب سريعة ممتعة عن توفير الماء والكهرباء</small><span class="px-tag">قريباً</span></button>
     </div>
    
    <div class="seg scroll" role="group" aria-label="نوع التحدي">
      ${Object.entries(PER).map(([k, v]) => `<button data-a="per" data-k="${k}" aria-pressed="${per == k}">${v}</button>`).join('')}
    </div>
    
    <div class="w cards three">${L.map(([c, i]) => {
      const cl = S.ch[i] == 1;
      const p = chP(i);
      const st = cl ? ['تم الاستلام', 1] : p >= 100 ? ['استلم المكافأة', 0] : p > 0 ? ['كمّل التقدم', 1] : ['لسه ما بدأتش', 1];
      return `
        <article class="glass kc kc-${CT[i]}">
          <div class="ch">
            <div class="ico">${ic(c[1])}</div>
            <div class="ch-body">
              <h3>${c[2]}</h3>
              <p>${c[3]}</p>
            </div>
            <span class="pill g" style="align-self:flex-start">${ar(c[4])} XP</span>
          </div>
          <div class="pg">
            <span class="track" role="progressbar" aria-label="تقدّم تحدي ${c[2]}" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100">
              <b class="fill" style="width:${p}%"></b>
            </span>
            <span>${ar(p)}٪</span>
          </div>
          <button class="btn" data-a="claim" data-i="${i}" ${st[1] ? 'disabled' : ''}>${st[0]} · ${ar(c[5])} بذرة</button>
        </article>
      `;
    }).join('')}</div>
  `;
}

function stats() {
  const w = weekVals();
  const d = ['سبت', 'أحد', 'اثنين', 'ثلاثاء', 'أربعاء', 'خميس', 'جمعة'];
  const td = (new Date().getDay() + 1) % 7;
  const r = S.read;
  return `
    <div class="w cols2"><div class="a">
    <section class="glass acc">
      <small>إجمالي توفيرك</small>
      <b>${ar(S.money)} ج.م</b>
    </section>
    <button class="btn s" data-a="shareimp" style="margin:0 0 .875rem">${ic('content_copy')}شارك أثرك</button>
    
    <div class="grid3">
      <div class="stat glass">
        <div class="ic-wrap" style="background:var(--water-light);color:var(--water)">${ic('water_drop')}</div>
        <b style="color:var(--water)">${ar(S.water)}</b>
        <small>لتر</small>
      </div>
      <div class="stat glass">
        <div class="ic-wrap" style="background:var(--gold-light);color:var(--gold-dark)">${ic('bolt')}</div>
        <b style="color:var(--gold-dark)">${ar(S.energy)}</b>
        <small>ك.و.س</small>
      </div>
      <div class="stat glass">
        <div class="ic-wrap" style="background:var(--accent-light);color:var(--accent)">${ic('local_fire_department')}</div>
        <b style="color:var(--accent)">${ar(S.streak)}</b>
        <small>يوم متواصل</small>
      </div>
    </div>
    </div>
    
    <section class="glass chartc">
      <div class="sec-in"><h2>توفيرك خلال الأسبوع</h2><span class="count">المجموع ${ar(w.reduce((a, b) => a + b, 0))} نقطة</span></div>
      <p class="sub" style="margin:.2rem 0 0">كل عمود هو النقاط اللي كسبتها من مهامك في اليوم</p>
      <p class="legend"><span class="lg-g"><i></i>الهدف اليومي ${ar(GOAL)} نقطة</span><span class="lg-t"><i></i>النهارده</span></p>
      <div class="cols" role="group" aria-label="توفيرك اليومي خلال الأسبوع بالنقاط">
        <i class="goal" style="bottom:${GOAL / SC * 100}%" aria-hidden="true"></i>
        ${w.map((v, i) => `<button class="col ${i == td ? 'td' : ''}" data-a="bar" data-i="${i}" style="--bh:${Math.max(v / SC * 100, 3)}" aria-label="${d[i]}: ${v ? ar(v) + ' نقطة' : 'لا توفير'}">
          <span class="bub" role="tooltip"><b>${d[i]}</b>${v ? ar(v) + ' نقطة' : 'لا توفير'}<small>${v >= GOAL ? 'حققت الهدف' : 'باقي ' + ar(GOAL - v) + ' للهدف'}</small></span>
          <span class="v">${v ? ar(v) : '—'}</span><i class="bar-fill ${v ? '' : 'z'}" style="height:${Math.max(v / SC * 100, 3)}%"></i>
        </button>`).join('')}
      </div>
      <div class="xl" aria-hidden="true">${d.map((n, i) => `<span class="${i == td ? 'td' : ''}">${n}</span>`).join('')}</div>
    </section>
    
    <section class="glass c">
      <h2>مقارنة استهلاك الكهرباء</h2>
      <p class="sub">من فاتورة الكهرباء، اكتب كام ك.و.س استهلكت في كل شهر ونحسبلك وفّرت كام.</p>
      <label for="r1">استهلاك الشهر ده (ك.و.س)</label>
      <input id="r1" type="number" inputmode="decimal" min="0" value="${r ? r.c : ''}">
      <label for="r2">استهلاك الشهر اللي فات (ك.و.س)</label>
      <input id="r2" type="number" inputmode="decimal" min="0" value="${r ? r.p : ''}">
      <label for="r3">قيمة فاتورة الشهر ده (جنيه) — اختياري</label>
      <input id="r3" type="number" inputmode="decimal" min="0" value="${r ? r.b : ''}">
      <div style="height:1rem"></div>
      <button class="btn" data-a="read">احسب توفيري</button>
      ${r ? `<p class="src" role="status" style="margin-top:1rem">${r.s > 0 ? `وفّرت ${ar(r.s)} ك.و.س = ${ar(r.m)} جنيه` : 'استهلاكك زاد — حاول الشهر الجاي'}</p>` : ''}
    </section>
    </div>
  `;
}

function ach() {
  const l = lvl();
  const lo = LV[l-1];
  const hi = LV[l] || LV[4];
  const p = l == 5 ? 100 : (S.xp - lo) / (hi - lo) * 100;
  const un = BG.map((_, i) => S.badges.includes(i) || BH[i][1](S));
  if (un.some((v, i) => v && !S.badges.includes(i))) { S.badges = un.map((v, i) => v ? i : -1).filter(i => i >= 0); save(); }
  const u = un.filter(Boolean).length;
  return `
    
    
    <section class="glass" style="margin-top:1rem">
      <div style="display:flex;justify-content:space-between;font-weight:700;font-size:.95rem">
        <span>المستوى ${ar(l)} · ${LN[l-1]}</span>
        <span style="color:var(--muted);font-weight:500">${ar(S.xp)} / ${ar(hi)} XP</span>
      </div>
      <div class="pg"><span class="track" role="progressbar" aria-label="تقدّم المستوى" aria-valuenow="${Math.round(p)}" aria-valuemin="0" aria-valuemax="100"><b class="fill" style="width:${p}%"></b></span></div>
    </section>
    
    <div class="sec">
      <h2>الأوسمة</h2>
      <span class="count">${ar(u)} / ${ar(BG.length)}</span>
    </div>
    
    <div class="bd">
      ${BG.map((b, i) => `
        <button class="b ${un[i] ? 'u' : ''}" style="--d:${(i % 6) * .45}s" data-a="badge" data-i="${i}" title="${un[i] ? 'اتفتح: ' : 'علشان تفتحه: '}${hintOf(BH[i][0])}" aria-label="${b[1]}، ${un[i] ? 'مفتوح' : 'مقفول، ' + BH[i][0]}">
          ${un[i] ? '' : ic('lock', 'lock')}
          <span class="med">${ic(b[0])}</span>
          <span class="bl">${b[1]}</span>
        </button>
      `).join('')}
    </div>
  `;
}

const norm = s => s.replace(/[أإآ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه').replace(/[\u064B-\u0652]/g, '').toLowerCase().replace(/ميه/g, 'ماء').replace(/لمبه/g, 'كهرباء');

function know() {
  const nq = norm(q), G = S.faith == 'g', band = S.age ? bandOf(S.age) : null;
  if (G && kf == 's') kf = 'a';
  const L = KN.map((k, i) => [k, i]).filter(([k]) => (!G || k[0] != 's') && (band == null || k[4] === band) && (kf == 'a' || k[0] == kf) && (!nq || norm(k[1] + k[2]).includes(nq)));
  const lv = band == null ? 'محتوى لكل المستويات' : 'محتوى مستوى ' + AGE_BANDS[band].ti + ' · ' + AGE_BANDS[band].de;
  return `
    <h1 style="margin-top:.5rem">${G ? 'معلومات عامة' : 'المعرفة والسنن'}</h1>
    <p class="sub" style="margin:.15rem 0 .6rem">${lv}</p>
    
    <div class="seg" role="group" aria-label="نوع المحتوى">
      ${[['a', 'الكل'], ['s', 'سنن'], ['t', 'نصائح']].filter(x => !(G && x[0] == 's')).map(([k, v]) => `<button data-a="kf" data-k="${k}" aria-pressed="${kf == k}">${v}</button>`).join('')}
    </div>
    
    <label for="q" class="sub" style="margin:0 0 .5rem">بحث</label>
    <input id="q" type="search" autocomplete="off" enterkeyhint="search" placeholder="${G ? 'ابحث عن نصيحة...' : 'ابحث عن سنّة أو نصيحة...'}" value="${esc(q)}">
    
    <div style="height:1rem"></div>
    
    <div class="w cards three">${L.length ? L.map(([k, i]) => {
      const d = S.pledged.includes(i);
      return `
        <article class="glass k kc kc-${k[3]}">
          <span class="pill ${k[0] == 's' ? 'a' : 'kp'}">${k[0] == 's' ? 'سنّة' : ic(KK[k[3]][1]) + 'نصيحة · ' + KK[k[3]][0]}</span>
          <p>${k[1]}</p>
          <div class="src">${k[2]}</div>
          <button class="btn ${d ? 's' : ''}" data-a="pledge" data-i="${i}" ${d ? 'disabled' : ''}>${d ? 'وعدت بتطبيقها' : 'أوعد إني هطبقها +' + ar(10) + ' XP'}</button>
        </article>
      `;
    }).join('') : `<div class="glass empty empty-st">${ILL.search}<h3>مفيش نتائج</h3><p>جرّب كلمة تانية زي «ماء» أو «كهرباء».</p></div>`}</div>
  `;
}

function prog() {
  return `<h1 style="margin-top:.5rem">تقدّمي</h1>
    <div class="seg" role="group" aria-label="القسم">${[['st', 'الإحصائيات'], ['bd', 'الأوسمة']].map(([k, v]) => `<button data-a="pt" data-k="${k}" aria-pressed="${pt == k}">${v}</button>`).join('')}</div>
    ${pt == 'st' ? stats() : ach()}`;
}

