/* ورق ملوّن: صغير مع كل مهمة، كتير مع مستوى جديد */
const cf = { ps: [], run: false, t: 0, id: 0 };
function confetti(kind) {
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const c = $('#cf'), x = c.getContext('2d'), W = innerWidth, H = innerHeight;
  if (!cf.run) { const d = Math.min(devicePixelRatio || 1, 1.5); c.width = W * d; c.height = H * d; cf.d = d; }
  const big = kind == 'b', n = big ? 110 : 22, cols = ['#2FA66B', '#F5C242', '#4AB3D9', '#F27B8C', '#9BE0B8', '#fff'], r = (a, b) => a + Math.random() * (b - a);
  for (let k = 0; k < n; k++) cf.ps.push({
    x: big ? r(0, W) : W / 2 + r(-110, 110), y: big ? r(-H * .35, -10) : r(-60, -10),
    vx: r(-2, 2), vy: big ? r(7, 12) : r(6, 10), w: r(6, 11), h: r(4, 8), a: r(0, 6.3), va: r(-.25, .25), c: cols[k % 6], o: Math.random() < .3
  });
  if (cf.ps.length > 160) cf.ps.splice(0, cf.ps.length - 160);
  cf.end = performance.now() + 2600;                  // أمان: الزينة تقف بعد ٢٫٦ ثانية مهما حصل
  if (cf.run) return;
  cf.run = true; cf.t = performance.now();
  (function loop(now) {
    const dt = Math.min((now - cf.t) / 16.7 || 1, 2.5); cf.t = now;     // حركة مبنية على الزمن، فما تتقلش على الأجهزة البطيئة
    x.setTransform(cf.d, 0, 0, cf.d, 0, 0); x.clearRect(0, 0, W, H);
    cf.ps = cf.ps.filter(p => p.y < H + 20);
    if (now > cf.end) cf.ps = [];
    cf.ps.forEach(p => {
      p.vy += .22 * dt; p.x += (p.vx + Math.sin(p.y / 30) * .6) * dt; p.y += p.vy * dt; p.a += p.va * dt;
      const co = Math.cos(p.a), si = Math.sin(p.a);
      x.setTransform(cf.d * co, cf.d * si, -cf.d * si, cf.d * co, cf.d * p.x, cf.d * p.y); x.fillStyle = p.c;
      p.o ? (x.beginPath(), x.arc(0, 0, p.w / 2.2, 0, 7), x.fill()) : x.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
    });
    if (cf.ps.length) requestAnimationFrame(loop); else { cf.run = false; x.setTransform(1, 0, 0, 1, 0, 0); x.clearRect(0, 0, c.width, c.height); }
  })(cf.t);
}

