const genCode = () => { const A = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789', r = crypto.getRandomValues(new Uint8Array(5)); return [...r].map(x => A[x % A.length]).join(''); };
const cleanCode = v => String(v || '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 8);
const myId = () => { if (!S.uid) { S.uid = genCode() + genCode(); save(); } return S.uid; };
const intList = (a, m) => Array.isArray(a) ? [...new Set(a.filter(v => Number.isInteger(v) && v >= 0 && v < m))] : [];
function repCode() { const o = { i: myId(), bi: S.badges, cc: S.ch.map((v, k) => v == 1 && CH[k][0] != 'd' ? k : -1).filter(k => k >= 0), n: S.name, a: S.age, x: S.xp, w: S.water, e: S.energy, m: S.money, s: S.streak, b: S.badges.length, t: S.tasks.filter(Boolean).length, c: S.cls, d: dayKey() }; return 'ATHR2.' + b64(new TextEncoder().encode(JSON.stringify(o))); }
function parseRep(s) {
  try {
    s = String(s).trim(); if (!/^ATHR[12]\./.test(s)) return null;
    const o = JSON.parse(new TextDecoder().decode(unb64(s.slice(6)))), n = v => Number.isFinite(+v) ? Math.max(0, +v) : 0;
    if (!o || typeof o.n != 'string' || !o.n.trim()) return null;
    return { i: String(o.i || '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 12), bi: intList(o.bi, BG.length), cc: intList(o.cc, CH.length), n: o.n.slice(0, 24), a: n(o.a), x: n(o.x), w: n(o.w), e: n(o.e), m: n(o.m), s: n(o.s), b: n(o.b), t: n(o.t), c: cleanCode(o.c), d: String(o.d || '').slice(0, 10) };
  } catch { return null; }
}
const copyTxt = (txt, ok, el) => {
  const fb = () => { try { const x = document.createElement('textarea'); x.value = txt; x.setAttribute('readonly', ''); x.style.cssText = 'position:fixed;top:0;left:0;opacity:0'; (document.querySelector('#ov .sheet') || document.body).appendChild(x); x.focus(); x.select(); x.setSelectionRange(0, txt.length); const r = document.execCommand('copy'); x.remove(); return r; } catch { return false; } };
  const manual = () => { if (el) { el.focus(); el.select(); toast('اضغط مطوّلًا على النص واختار نسخ'); } else { try { prompt('انسخ من هنا', txt); } catch {} } };
  const done = r => r ? toast(ok) : manual();
  if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(txt).then(() => toast(ok), () => done(fb())); else done(fb());
};
