/* ── اللعب الجماعي والمبارزة: من نفس بنك الأسئلة، على قد السن — الشكل: [المستوى، ٠، السؤال، الاختيارات، الصح، السبب] ── */
function gPool(n, three) {
  const out = [], used = new Set(), seen = new Set(S.seen);
  const all = QB.map((q, i) => [q, i]).filter(([q]) => !three || (q[3].length >= 3 && !q[5]));
  for (let g = 0; out.length < n && g < n * 30; g++) {
    const L = rollLvl();
    let pool = all.filter(([q, i]) => q[1] == L && !used.has(i) && !seen.has(i));
    if (!pool.length) pool = all.filter(([q, i]) => q[1] == L && !used.has(i));
    if (!pool.length) pool = all.filter(([, i]) => !used.has(i));
    if (!pool.length) break;
    const [q, i] = pool[Math.floor(Math.random() * pool.length)];
    let o = q[3], c = q[4];
    if (three && o.length > 3) {   // المبارزة ليها ٣ أزرار بس: الصح + غلطتين عشوائيتين من الاختيارات الأربعة
      const keep = [c, ...o.map((_, j) => j).filter(j => j != c).sort(() => Math.random() - .5).slice(0, 2)].sort((a, b) => a - b);
      o = keep.map(j => o[j]); c = keep.indexOf(c);
    }
    used.add(i); out.push([q[1], 0, q[2], o, c, 'الإجابة الصحيحة: ' + o[c] + (q[6] ? '. ' + q[6] : '')]);
  }
  used.forEach(i => S.seen.push(i)); if (S.seen.length > 1200) S.seen = S.seen.slice(-1200);
  return out;
}

