/* ── كلمة المرور: ما بتتخزنش نص عادي. PBKDF2-SHA256 + salt عشوائي لكل كلمة (Web Crypto، من غير مكتبات) ── */
const PIN_ITER = 600000;
const b64 = u => btoa(String.fromCharCode(...u));
const unb64 = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));
const hasCrypto = () => !!(window.crypto && crypto.subtle && crypto.getRandomValues);
async function pinDerive(pin, salt, iter) {
  const k = await crypto.subtle.importKey('raw', new TextEncoder().encode(pin), 'PBKDF2', false, ['deriveBits']);
  return new Uint8Array(await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt, iterations: iter }, k, 256));
}
async function pinHash(pin) {
  if (!hasCrypto()) return pin;                       // متصفح قديم/سياق غير آمن: بنحتفظ بالشكل القديم بدل ما التطبيق يقف
  const salt = crypto.getRandomValues(new Uint8Array(16));
  return `p1$${PIN_ITER}$${b64(salt)}$${b64(await pinDerive(pin, salt, PIN_ITER))}`;
}
async function pinCheck(pin, stored) {
  if (/^\d{4}$/.test(stored)) {                       // كلمة مرور قديمة مخزنة نص عادي: نتحقق ثم نحوّلها لتجزئة فورًا
    const ok = pin === stored;
    if (ok && hasCrypto()) { S.pin = await pinHash(pin); save(); }
    return ok;
  }
  const m = /^p1\$(\d+)\$([^$]+)\$([^$]+)$/.exec(stored);
  if (!m || !hasCrypto()) return false;
  const a = await pinDerive(pin, unb64(m[2]), +m[1]), b = unb64(m[3]);
  let d = a.length ^ b.length;                        // مقارنة بزمن ثابت
  for (let i = 0; i < a.length; i++) d |= a[i] ^ (b[i] || 0);
  return d === 0;
}
const weakPin = p => /^(\d)\1{3}$/.test(p) || '0123456789'.includes(p) || '9876543210'.includes(p);

