const runSearch = el => {
  q = el.value;
  const p = el.selectionStart;
  render();
  const n = $('#q');
  n.focus();
  n.setSelectionRange(p, p);
};
document.addEventListener('input', e => { if (e.target.id == 'q' && !e.isComposing) runSearch(e.target); });
document.addEventListener('compositionend', e => { if (e.target.id == 'q') runSearch(e.target); });

document.addEventListener('keydown', e => {
  const o = $('#ov');
  if (e.key == 'Escape' && !o.hidden && !o.dataset.lock) close();
  if (e.key == 'Enter' && e.target.tagName == 'INPUT' && e.target.closest('.sheet')) {   // Enter يأكّد النموذج
    const b = e.target.closest('.sheet').querySelector('.btn:not(.s):not(.d)');
    if (b) { e.preventDefault(); b.click(); }
  }
});

/* ═══════════════════════════════════════════════
   SETUP WIZARD — أول مرة
   ═══════════════════════════════════════════════ */
function setupWizard() {
  window._wz = { step: 0, role: '', name: '', age: '', cn: '', faith: 's', kwh: '1.10', water: '0.0025' };
  wzRender(true);
}
const wzR = () => ROLES[window._wz.role] || null;
const wzSteps = () => ['role', 'who', 'faith', 'prices', 'pin'];
/* أزرار السن من ٩ لـ ١٨، كل زر مستقل ومقسم لثلاث مراحل */
const ageChips = (cur, a) => {
  const ages = Array.from({ length: 10 }, (_, k) => k + 9);
  const legend = AGE_BANDS.map(b => `<span class="al al-${b.key}">${ar(b.min)}–${ar(b.max)} سنة · ${b.ti}</span>`).join('');
  return `<div class="age-chips" role="group" aria-label="اختار السن من ٩ لـ ١٨">${ages.map(n => `<button class="btn s" type="button" data-a="${a}" data-i="${n}" aria-pressed="${+cur == n}">${ar(n)}</button>`).join('')}</div><p class="age-legend">${legend}</p>`;
};
/* لما حد يختار سنه: الشاشة تطلع لمربع الكتابة وتنوّره */
function ageFocus(e) {
  if (!e) return;
  const rm = matchMedia('(prefers-reduced-motion: reduce)').matches;
  try { e.scrollIntoView({ behavior: rm ? 'auto' : 'smooth', block: 'center' }); } catch { e.scrollIntoView(); }
  e.classList.remove('age-pop'); void e.offsetWidth; e.classList.add('age-pop');
  if (matchMedia('(hover:hover)').matches) { try { e.focus({ preventScroll: true }); } catch {} }
}
const roleOpt = (a, r, on) => {
  const B = ROLE_BTNS[r], R = B || ROLES[r];
  if (B) return `<button class="wz-opt soon" type="button" disabled aria-disabled="true"><span class="wz-ico">${ic(R.ic)}</span><span><b>${R.ti}<span class="soon-badge">قريباً</span></b><small>${R.de}</small></span></button>`;
  return `<button class="wz-opt ${on ? 'on' : ''}" data-a="${a}" data-r="${r}" type="button"><span class="wz-ico">${ic(R.ic)}</span><span><b>${R.ti}</b><small>${R.de}</small></span></button>`;
};
function wzHtml() {
  const W = window._wz, ks = wzSteps(), n = W.step, N = ks.length, k = ks[n], R = wzR();
  const bar = `<div class="wz-top"><div class="wz-steps" role="progressbar" aria-valuemin="1" aria-valuemax="${N}" aria-valuenow="${n + 1}" aria-label="الخطوة ${ar(n + 1)} من ${ar(N)}">${ks.map((_, q) => `<i class="${q < n ? 'done' : q == n ? 'on' : ''}"></i>`).join('')}</div><span class="wz-count">الخطوة ${ar(n + 1)} من ${ar(N)}</span></div>`;
  const back = n ? `<button class="btn s" data-a="wzBack" type="button">رجوع</button>` : '';
  const next = `<button class="btn" data-a="wzNext" type="button">التالي</button>`;
  const opt = (a, d, ic_, ti, de, on) => `<button class="wz-opt ${on ? 'on' : ''}" data-a="${a}" ${d} type="button"><span class="wz-ico">${ic(ic_)}</span><span><b>${ti}</b><small>${de}</small></span></button>`;
  let body, act;
  if (k == 'role') {
    body = `<div class="wz-hero">${ILL.welcome}</div><p class="wz-kick">أهلاً بيك في أثر</p><h2>من أنت؟</h2><p class="sub">اضغط «أنا مستخدم» وحدد سنّك، لأن الأسئلة والنصائح هتظبط على مستواك.</p>
      ${Object.keys(ROLE_BTNS).map(r => roleOpt('wzRole', r, W.role == r)).join('')}<p id="soonMsg" class="src" role="status" aria-live="polite" hidden>ستتوفر هذه الميزة في الإصدار الثاني</p>`;
    act = '';
  } else if (k == 'who') {
    const T = R.k == 'teacher', Pa = R.k == 'parent';
    body = `<div class="wz-hero"><div class="wz-badge">${ic(R.ic)}</div></div><p class="wz-kick">${R.ti}</p><h2>${T ? 'بيانات الفصل' : Pa ? 'بيانات ابنك أو بنتك' : 'اسمك وسنّك'}</h2>
      <div class="wz-card"><label for="sp5">${Pa ? 'اسم الطفل' : 'اسمك'}</label><input id="sp5" type="text" maxlength="24" autocomplete="off" value="${esc(W.name)}">
      ${T ? `<label for="sp8">اسم الفصل (اختياري)</label><input id="sp8" type="text" maxlength="30" autocomplete="off" placeholder="مثلاً: الصف الخامس أ" value="${esc(W.cn)}">` : ''}
      <label for="sp6">${T ? 'سن الطلاب (اختياري)' : Pa ? 'سن الطفل' : R.age == 2 ? 'سنّك' : 'سنّك (اختياري)'}</label><input id="sp6" type="number" inputmode="numeric" min="9" max="18" placeholder="من ٩ لـ ١٨" value="${esc(W.age)}">
      ${ageChips(W.age, 'wzAge')}
      <p class="wz-hint">${ic('info')}<span>السن بيظبط صعوبة الأسئلة وبساطة الكلام. بنقبل من ٩ لحد ١٨ سنة، وكل مرحلة ليها أسئلتها ونصائحها.</span></p></div>`;
    act = `${back}${next}`;
  } else if (k == 'faith') {
    body = `<div class="wz-hero"><div class="wz-badge">${ic('menu_book')}</div></div><h2>نوع المحتوى</h2><p class="sub">تقدر تغيّره بعدين من الإعدادات.</p>
      ${opt('wzFaith', 'data-f="g"', 'lightbulb', 'معلومات عامة', 'نصائح وأسئلة عن الماء والكهرباء', W.faith == 'g')}
      ${opt('wzFaith', 'data-f="s"', 'menu_book', 'معلومات عامة وسنن', 'تشمل كمان آيات وأحاديث عن ترشيد الاستهلاك', W.faith == 's')}`;
    act = `${back}${next}`;
  } else if (k == 'prices') {
    body = `<div class="wz-hero"><div class="wz-badge">${ic('payments')}</div></div><h2>أسعار البيت</h2><p class="sub">بنحسب بيها كام جنيه وفّرت. أرقام تقريبية.</p>
      <div class="wz-card">
      <div class="wz-row"><span class="wz-ico e">${ic('bolt')}</span><div class="grow"><label for="sp3">سعر الكيلوواط</label><input id="sp3" type="number" inputmode="decimal" step="0.01" min="0" value="${esc(W.kwh)}"><div class="wz-unit">جنيه لكل ك.و.س</div></div></div>
      <div class="wz-row"><span class="wz-ico w">${ic('water_drop')}</span><div class="grow"><label for="sp4">سعر الماء</label><input id="sp4" type="number" inputmode="decimal" step="0.0001" min="0" value="${esc(W.water)}"><div class="wz-unit">جنيه لكل لتر</div></div></div></div>`;
    act = `${back}${next}`;
  } else {
    body = `<div class="wz-hero"><div class="wz-badge">${ic('shield')}</div></div><h2>${R.k == 'child' ? 'كلمة مرور (يعرفها ولي أمرك)' : 'كلمة المرور'}</h2><p class="sub">٤ أرقام بتحمي الإعدادات والتقارير والنسخ الاحتياطية.</p>
      <div class="wz-card"><label for="sp1">كلمة المرور</label><input id="sp1" class="wz-pin" type="password" inputmode="numeric" autocomplete="off" maxlength="4" placeholder="••••">
      <label for="sp2">تأكيد كلمة المرور</label><input id="sp2" class="wz-pin" type="password" inputmode="numeric" autocomplete="off" maxlength="4" placeholder="••••">
      <p class="wz-hint">${ic('lock')}<span>اختار أرقام مش سهلة التخمين.</span></p></div>`;
    act = `${back}<button class="btn" data-a="setupSave" type="button">ابدأ الرحلة</button>`;
  }
  return `<div class="wz-wrap">${bar}${body}${act ? `<div class="wz-act">${act}</div>` : ''}</div>`;
}
function wzRender(first) {
  if (first) modal(wzHtml(), { lock: 1 });
  else {
    const sh = $('#ov .sheet'); if (!sh) return;
    sh.innerHTML = wzHtml(); sh.scrollTop = 0;
    const hd = sh.querySelector('h2'); if (hd) hd.id = 'dlgT';
    const f = sh.querySelector('input'); if (f) f.focus({ preventScroll: true });
  }
  const sh = $('#ov .sheet'); if (sh) sh.classList.add('wz');
}
function wzStep(d) {
  const W = window._wz; if (!W) return;
  const k = wzSteps()[W.step], g = id => { const e = document.getElementById(id); return e ? e.value : null; };
  if (k == 'who') {
    W.name = (g('sp5') || '').trim().slice(0, 24);
    if (g('sp6') !== null) W.age = g('sp6'); if (g('sp8') !== null) W.cn = g('sp8').trim().slice(0, 30);
    const R = ROLES[W.role] || ROLES.user, a = +W.age, has = String(W.age).trim() !== '';
    if (d > 0 && (R.age == 2 || has) && !(a >= 9 && a <= 18)) { toast('اكتب السن من ٩ لـ ١٨ سنة'); $('#sp6').focus(); return; }
  }
  if (k == 'prices') {
    W.kwh = g('sp3'); W.water = g('sp4');
    const a = +W.kwh, w = +W.water;
    if (d > 0 && (!(a > 0 && a < 1000) || !(w > 0 && w < 100))) { toast('اكتب سعرين أكبر من صفر'); $('#sp3').focus(); return; }
  }
  W.step = Math.max(0, Math.min(wzSteps().length - 1, W.step + d));
  wzRender(false);
}


