      const from = (changed || prevMini == null) ? c0 : prevMini;
      if (String(from) !== String(to)) mf.animate([{ strokeDashoffset: from }, { strokeDashoffset: to }], { duration: 900, easing: 'cubic-bezier(.3,1.1,.5,1)' });
      prevMini = to;
