      const put = r => { ind.style.left = r.x + 'px'; ind.style.top = r.y + 'px'; ind.style.width = r.w + 'px'; ind.style.height = r.h + 'px'; };
      g.classList.add('has-ind'); g.prepend(ind);
      put(from || to);
