/* سحب المهمة لإنجازها (على اللمس فقط): أي اتجاه، وبعدها يفتح سؤال المهمة زي الضغط */
(() => {
  let el = null, x0 = 0, y0 = 0, on = false, go = false, swiped = 0, prog = false;
  const TH = 84;
  document.addEventListener('pointerdown', e => {
    if (e.pointerType != 'touch') return;
    const t = e.target.closest('.task');
    if (!t || t.classList.contains('done')) return;
    el = t; x0 = e.clientX; y0 = e.clientY; on = false; go = false;
  }, { passive: true });
  document.addEventListener('pointermove', e => {
    if (!el) return;
    const mx = e.clientX - x0, my = e.clientY - y0;
    if (!on) {
      if (Math.abs(mx) > 12 && Math.abs(mx) > Math.abs(my) * 1.6) { on = true; el.classList.add('swp'); }
      else { if (Math.abs(my) > 12) el = null; return; }
    }
    el.style.transform = `translateX(${Math.max(-TH * 1.4, Math.min(TH * 1.4, mx * .6))}px)`;   // حد أقصى: المهمة ما تخرجش بعيد برة الشاشة
    const r = Math.abs(mx) > TH;
    if (r != go) { go = r; el.classList.toggle('rdy', r); if (r) buzz(10); }
  }, { passive: true });
  const end = fire => {
    if (!el) return;
    const t = el, was = on, ok = go;
    el = null; on = false; go = false;
    t.classList.remove('swp', 'rdy'); t.style.transform = '';
    if (was) swiped = Date.now();
    if (fire && was && ok) { prog = true; t.click(); prog = false; }
  };
  document.addEventListener('pointerup', () => end(true), { passive: true });
  document.addEventListener('pointercancel', () => end(false), { passive: true });
  /* لو المتصفح ولّد click بعد السحب، نتجاهله */
  document.addEventListener('click', e => {
    if (!prog && Date.now() - swiped < 350 && e.target.closest('.task')) { e.stopImmediatePropagation(); e.preventDefault(); }
  }, true);
})();

